import {captureOperation,notifyCaptures} from './capture-store.js';
const $=id=>document.getElementById(id),canvas=$('canvas'),overlay=$('overlay'),ctx=canvas.getContext('2d'),previewCtx=overlay.getContext('2d');
const id=new URLSearchParams(location.search).get('capture');
let base=null,marks=[],history=[],future=[],tool='pen',selected=-1,gesture=null,crop=null,textPoint=null,item=null,loading=false,loaded=false,dirty=false,pollTimer;
function status(message,error=false){$('editorStatus').textContent=message;$('editorStatus').classList.toggle('error',error)}
function cloneMarks(){return structuredClone(marks)}
function checkpoint(){history.push({base,marks:cloneMarks()});if(history.length>50)history.shift();future=[];dirty=true}
function restore(state){base=state.base;marks=state.marks;selected=-1;gesture=null;crop=null;dirty=true;render();fit()}
function rect(a,b){return{x:Math.min(a.x,b.x),y:Math.min(a.y,b.y),w:Math.abs(a.x-b.x),h:Math.abs(a.y-b.y)}}
function bounds(mark){if(mark.type==='text'){const lines=mark.text.split('\n');ctx.save();ctx.font=`600 ${mark.size}px system-ui, sans-serif`;const w=Math.max(...lines.map(t=>ctx.measureText(t).width),1);ctx.restore();return{x:mark.x,y:mark.y,w,h:lines.length*mark.size*1.25}}if(mark.type==='pen'){const xs=mark.points.map(p=>p.x),ys=mark.points.map(p=>p.y);return{x:Math.min(...xs),y:Math.min(...ys),w:Math.max(...xs)-Math.min(...xs),h:Math.max(...ys)-Math.min(...ys)}}return rect({x:mark.x,y:mark.y},{x:mark.x+mark.w,y:mark.y+mark.h})}
function drawMark(context,mark){context.save();context.strokeStyle=mark.color;context.fillStyle=mark.color;context.lineWidth=mark.width;context.lineCap='round';context.lineJoin='round';context.setLineDash([]);if(mark.type==='text'){context.font=`600 ${mark.size}px system-ui, sans-serif`;context.textBaseline='top';mark.text.split('\n').forEach((line,i)=>context.fillText(line,mark.x,mark.y+i*mark.size*1.25))}else if(mark.type==='pen'){context.beginPath();mark.points.forEach((p,i)=>i?context.lineTo(p.x,p.y):context.moveTo(p.x,p.y));if(mark.points.length===1){context.arc(mark.points[0].x,mark.points[0].y,mark.width/2,0,Math.PI*2);context.fill()}else context.stroke()}else if(mark.type==='arrow'){const x=mark.x+mark.w,y=mark.y+mark.h,angle=Math.atan2(mark.h,mark.w),head=Math.max(12,mark.width*4);context.beginPath();context.moveTo(mark.x,mark.y);context.lineTo(x,y);context.moveTo(x-head*Math.cos(angle-.5),y-head*Math.sin(angle-.5));context.lineTo(x,y);context.lineTo(x-head*Math.cos(angle+.5),y-head*Math.sin(angle+.5));context.stroke()}else{const b=bounds(mark);if(mark.type==='rect')context.strokeRect(b.x,b.y,b.w,b.h);if(mark.type==='ellipse'){context.beginPath();context.ellipse(b.x+b.w/2,b.y+b.h/2,b.w/2,b.h/2,0,0,Math.PI*2);context.stroke()}if(mark.type==='redact'){context.fillStyle='#000';context.fillRect(Math.floor(b.x),Math.floor(b.y),Math.ceil(b.w),Math.ceil(b.h))}}context.restore()}
function render(){if(!base)return;if(canvas.width!==base.width||canvas.height!==base.height){canvas.width=overlay.width=base.width;canvas.height=overlay.height=base.height}ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(base,0,0);marks.forEach(mark=>drawMark(ctx,mark));renderOverlay();$('dimensions').textContent=`${canvas.width} × ${canvas.height} px`;$('undo').disabled=!history.length;$('redo').disabled=!future.length;$('deleteMark').disabled=selected<0;$('cropActions').hidden=!crop||(gesture?.type==='draw'&&tool==='crop');if(crop)$('cropSize').textContent=`Crop to ${Math.round(crop.w)} × ${Math.round(crop.h)} px`}
function renderOverlay(){previewCtx.clearRect(0,0,overlay.width,overlay.height);previewCtx.save();if(selected>=0&&marks[selected]){const b=bounds(marks[selected]);previewCtx.strokeStyle='#4f7ff5';previewCtx.lineWidth=Math.max(1,1/currentScale());previewCtx.setLineDash([5/currentScale(),4/currentScale()]);previewCtx.strokeRect(b.x-4,b.y-4,b.w+8,b.h+8)}if(crop){previewCtx.fillStyle='#16233780';previewCtx.fillRect(0,0,overlay.width,overlay.height);previewCtx.clearRect(crop.x,crop.y,crop.w,crop.h);previewCtx.strokeStyle='#fff';previewCtx.lineWidth=2/currentScale();previewCtx.setLineDash([6/currentScale(),4/currentScale()]);previewCtx.strokeRect(crop.x,crop.y,crop.w,crop.h)}else if(gesture?.mark)drawMark(previewCtx,gesture.mark);previewCtx.restore()}
function currentScale(){return canvas.getBoundingClientRect().width/canvas.width||1}
function fit(){if(!base)return;const choice=$('zoom').value;const scale=choice==='fit'?Math.min(1,Math.max(50,$('workspace').clientWidth-50)/canvas.width,Math.max(50,$('workspace').clientHeight-50)/canvas.height):+choice;$('canvasHolder').style.width=`${Math.max(1,canvas.width*scale)}px`;$('canvasHolder').style.height=`${Math.max(1,canvas.height*scale)}px`;renderOverlay()}
new ResizeObserver(fit).observe($('workspace'));$('zoom').onchange=fit;
function zoomBy(factor){if(!base)return;const target=Math.min(2,Math.max(.25,currentScale()*factor));const choices=[.25,.5,.75,1,1.5,2];$('zoom').value=String(choices.reduce((a,b)=>Math.abs(b-target)<Math.abs(a-target)?b:a));fit()}
$('zoomIn').onclick=()=>zoomBy(1.5);$('zoomOut').onclick=()=>zoomBy(1/1.5);
function position(e){const r=overlay.getBoundingClientRect();return{x:Math.max(0,Math.min(canvas.width,(e.clientX-r.left)*canvas.width/r.width)),y:Math.max(0,Math.min(canvas.height,(e.clientY-r.top)*canvas.height/r.height))}}
function commitText(){if(!textPoint)return;const text=$('inlineText').value.trim();if(text){checkpoint();marks.push({type:'text',...textPoint,text,color:$('color').value,size:+$('fontSize').value,width:+$('stroke').value})}textPoint=null;$('inlineText').hidden=true;render()}
function cancelText(){textPoint=null;$('inlineText').hidden=true}
function startText(point,text='',index=-1){textPoint=point;const input=$('inlineText');input.value=text;input.style.left=`${point.x/canvas.width*100}%`;input.style.top=`${point.y/canvas.height*100}%`;input.style.fontSize=`${+$('fontSize').value*currentScale()}px`;input.style.color=$('color').value;input.hidden=false;input.focus()}
$('inlineText').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();commitText()}if(e.key==='Escape'){e.preventDefault();cancelText()}};
function setTool(next){commitText();gesture=null;crop=null;selected=-1;tool=next;document.querySelectorAll('[data-tool]').forEach(b=>{b.classList.toggle('active',b.dataset.tool===next);b.setAttribute('aria-pressed',b.dataset.tool===next)});overlay.style.cursor=next==='select'?'default':'crosshair';const hints={select:'Click an annotation to select it. Drag to move it, or press Delete.',pen:'Drag to draw a freehand line. Click to make a dot.',rect:'Drag in any direction to draw a rectangle.',ellipse:'Drag to draw an ellipse.',arrow:'Drag from the start toward the point you want to highlight.',text:'Click the image, type your text, then press Enter. Shift + Enter adds a new line.',redact:'Drag over private information to cover its pixels with solid black.',crop:'Drag to choose an area, then select Apply crop. Cancel keeps the full image.'};$('toolHint').textContent=hints[next];render()}
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));
function hit(point){for(let i=marks.length-1;i>=0;i--){const b=bounds(marks[i]),pad=Math.max(6/currentScale(),marks[i].width);if(point.x>=b.x-pad&&point.x<=b.x+b.w+pad&&point.y>=b.y-pad&&point.y<=b.y+b.h+pad)return i}return -1}
function moveMark(mark,dx,dy){if(mark.type==='pen')mark.points.forEach(p=>{p.x+=dx;p.y+=dy});else{mark.x+=dx;mark.y+=dy}}
overlay.onpointerdown=e=>{if(!base||e.button!==0||gesture)return;e.preventDefault();commitText();const point=position(e);if(tool==='text'){startText(point);return}overlay.setPointerCapture(e.pointerId);if(tool==='select'){selected=hit(point);gesture=selected<0?null:{type:'move',pointer:e.pointerId,start:point,original:structuredClone(marks[selected]),before:cloneMarks()};render();return}crop=null;selected=-1;gesture={type:'draw',pointer:e.pointerId,start:point,mark:tool==='crop'?null:{type:tool,x:point.x,y:point.y,w:0,h:0,points:[point],color:$('color').value,width:+$('stroke').value}};render()};
overlay.onpointermove=e=>{if(!gesture||gesture.pointer!==e.pointerId)return;const point=position(e);if(gesture.type==='move'){marks[selected]=structuredClone(gesture.original);moveMark(marks[selected],point.x-gesture.start.x,point.y-gesture.start.y);render();return}if(tool==='crop'){crop=rect(gesture.start,point);render()}else{const mark=gesture.mark;if(mark.type==='pen')mark.points.push(point);else{mark.w=point.x-gesture.start.x;mark.h=point.y-gesture.start.y}renderOverlay()}};
function endGesture(e){if(!gesture||gesture.pointer!==e.pointerId)return;overlay.onpointermove(e);const active=gesture;gesture=null;if(active.type==='move'){const changed=JSON.stringify(active.before)!==JSON.stringify(marks);if(changed){history.push({base,marks:active.before});if(history.length>50)history.shift();future=[];dirty=true}}else if(tool==='crop'){if(!crop||crop.w<2||crop.h<2)crop=null;else crop={x:Math.floor(crop.x),y:Math.floor(crop.y),w:Math.floor(crop.w),h:Math.floor(crop.h)}}else if(active.mark.type==='pen'||Math.abs(active.mark.w)>1||Math.abs(active.mark.h)>1){checkpoint();marks.push(active.mark)}render()}
overlay.onpointerup=endGesture;
function cancelGesture(){if(gesture?.type==='move')marks=gesture.before;gesture=null;crop=null;render()}
overlay.onpointercancel=cancelGesture;overlay.onlostpointercapture=()=>{if(gesture)cancelGesture()};
function applyCrop(){if(!crop)return;commitText();const area=crop;checkpoint();render();const next=document.createElement('canvas');next.width=area.w;next.height=area.h;next.getContext('2d').drawImage(canvas,area.x,area.y,area.w,area.h,0,0,area.w,area.h);base=next;marks=[];crop=null;selected=-1;render();fit();status('Crop applied. Undo restores the full image.')}
$('applyCrop').onclick=applyCrop;$('cancelCrop').onclick=()=>{crop=null;render();status('Crop cancelled.')};
function undo(){cancelText();cancelGesture();if(!history.length)return;future.push({base,marks:cloneMarks()});restore(history.pop());status('Undone.')}
function redo(){cancelText();cancelGesture();if(!future.length)return;history.push({base,marks:cloneMarks()});restore(future.pop());status('Redone.')}
$('undo').onclick=undo;$('redo').onclick=redo;
function deleteSelected(){if(selected<0)return;checkpoint();marks.splice(selected,1);selected=-1;render();status('Annotation deleted.')}
$('deleteMark').onclick=deleteSelected;
for(const key of ['color','stroke','fontSize'])$(key).onchange=()=>{if(selected<0)return;checkpoint();if(key==='color')marks[selected].color=$(key).value;if(key==='stroke')marks[selected].width=+$(key).value;if(key==='fontSize'&&marks[selected].type==='text')marks[selected].size=+$(key).value;render()};
window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return}if(e.metaKey||e.ctrlKey||e.altKey)return;if(e.key==='Escape'){cancelText();cancelGesture();selected=-1;render()}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected()}const next={v:'select',p:'pen',r:'rect',e:'ellipse',a:'arrow',t:'text',b:'redact',c:'crop'}[e.key.toLowerCase()];if(next)setTool(next)});
function png(){commitText();if(crop)throw new Error('Apply or cancel the crop before copying or saving.');return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Could not export this image.')),'image/png'))}
$('copy').onclick=()=>{if(!loaded)return;try{if(!navigator.clipboard?.write||!globalThis.ClipboardItem)throw new Error('Image copying is unavailable in this browser. Use Download PNG.');const promise=png();const operation=navigator.clipboard.write([new ClipboardItem({'image/png':promise})]);operation.then(()=>status('Image copied. Paste it with ⌘V or Ctrl+V.')).catch(e=>status(e.name==='NotAllowedError'?'Clipboard access was denied. Allow clipboard access or download the PNG.':e.message,true))}catch(e){status(e.message,true)}};
$('download').onclick=async()=>{try{const blob=await png();const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`${(item?.name||'Screenshot').replace(/[^a-z0-9 _-]/gi,'').trim()||'Screenshot'}.png`;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status('PNG downloaded.')}catch(e){status(e.message,true)}};
$('save').onclick=async()=>{try{const blob=await png();item={...item,blob,meta:{...item.meta,width:canvas.width,height:canvas.height},updated:Date.now()};await captureOperation('put',item);notifyCaptures();dirty=false;status('Edited screenshot saved to your capture library.')}catch(e){status('Could not save: '+e.message+'. Copy or download to keep your edits.',true)}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
async function loadCapture(capture){if(loaded||loading||!capture?.blob)return;loading=true;try{const image=await createImageBitmap(capture.blob);base=document.createElement('canvas');base.width=image.width;base.height=image.height;base.getContext('2d').drawImage(image,0,0);image.close();item=capture;loaded=true;clearInterval(pollTimer);$('loading').hidden=true;$('canvasHolder').hidden=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);render();fit();status('Screenshot ready. Edit, copy, download, or save to your library.')}catch(e){status('Could not open the screenshot: '+e.message,true)}finally{loading=false}}
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===window.opener&&e.data?.type==='capture-ready'&&e.data.id===id)loadCapture(e.data.item)});
async function checkCapture(){if(!id||loaded||loading)return;try{const capture=await captureOperation('get',id);if(capture)await loadCapture(capture)}catch{status('Browser storage unavailable. Waiting for the original tab to send the screenshot.')}}
document.querySelectorAll('button:not(#retry)').forEach(b=>b.disabled=true);
if(!id){$('loadHint').textContent='Open a screenshot from Capture Studio to edit it.';status('No screenshot selected.',true)}else{window.opener?.postMessage({type:'editor-ready',id},location.origin);checkCapture();pollTimer=setInterval(checkCapture,500);setTimeout(()=>{if(!loaded){$('loadHint').textContent='Complete capture in the original tab, or reopen a screenshot from your library.';$('retry').hidden=false}},30000)}
$('retry').onclick=()=>{window.opener?.postMessage({type:'editor-ready',id},location.origin);checkCapture()};
